-- =============================================================================
-- 441 — LE CAHIER D'EXERCICES DE TLE (partie 6)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/Tle/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 441 --niveau Tle --matieres hggsp,emc --suffixe 6 > supabase/contenu/441_exercices_tle_6.sql
--
-- 108 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   emc.k146                36 exercices · 12 chapitres
--   hggsp.k152              36 exercices · 12 chapitres
--   hggsp.k153              36 exercices · 12 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('99b79047-e0f8-53b6-83fd-381be01e0b49'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Qui comptait à Athènes ?","competence":"lire-graphique","situation":"Au Ve siècle avant J.-C., Athènes est célèbre pour sa démocratie. Un graphique compare les habitants qui avaient des droits politiques et les autres.","documents":[{"id":"ath","type":"graphique","forme":"barres","titre":"Les habitants d’Athènes","source":"Ordres de grandeur arrondis, Athènes, Ve siècle avant J.-C.","categories":["Citoyens","Femmes, métèques et esclaves"],"series":[{"nom":"Habitants","valeurs":[40,260],"teinte":"violet"}],"axeY":{"titre":"Habitants","unite":"en milliers","min":0,"max":300,"pas":50},"axeX":{"titre":"Groupe"}}],"questions":[{"enonce":"Touche la barre du groupe qui possédait tous les droits politiques.","aide":"Les droits politiques appartenaient aux citoyens.","type":"zone","document":"ath","multiple":false},{"enonce":"Combien d’habitants (en milliers) n’avaient aucun droit politique ?","aide":"Lis la hauteur de la seconde barre.","type":"nombre","unite":"milliers"},{"enonce":"Environ quelle part des habitants (en %) étaient citoyens ? Arrondis à l’unité.","aide":"Divise 40 par le total 300, puis multiplie par 100.","type":"nombre","unite":"%"},{"enonce":"Que montre ce graphique sur la démocratie athénienne ?","aide":"Compare la première barre à la seconde.","type":"choix","options":[{"id":"a","texte":"Que les droits politiques n’appartenaient qu’à une petite minorité d’habitants"},{"id":"b","texte":"Que les esclaves formaient une minorité très réduite de la population totale"},{"id":"c","texte":"Que la démocratie athénienne était réservée aux seuls habitants les plus riches"},{"id":"d","texte":"Que presque tous les habitants votaient lors de chaque assemblée du peuple"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k0"]},"explication":"Les **citoyens** votaient et exerçaient les magistratures : environ 40 000 personnes."},{"cle":{"type":"nombre","valeur":260,"tolerance":0},"affichage":"260 milliers","explication":"Les femmes, les métèques et les esclaves représentent environ **260 000** habitants."},{"cle":{"type":"nombre","valeur":13,"tolerance":1},"affichage":"13 %","explication":"40 ÷ 300 ≈ 0,133 : environ **13 %** des habitants seulement."},{"cle":{"type":"choix","ids":["a"]},"explication":"La démocratie athénienne était directe mais **réservée à une minorité** : la première question est toujours « qui fait partie du peuple ? »."}]$ex$::jsonb),
  ('99b79047-e0f8-53b6-83fd-381be01e0b49'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le vote s’ouvre, étape par étape","competence":"se-reperer-temps","situation":"Clairval est un village imaginaire. Pour comprendre les règles du vote, Noé observe d’abord la frise de l’extension du suffrage en France, puis un petit cas censitaire.","documents":[{"id":"frise","type":"frise","titre":"L’extension du suffrage en France","source":"Dates du cours.","debut":1840,"fin":1980,"pas":20,"evenements":[{"id":"z1","date":1848,"nom":"Suffrage masculin"},{"id":"z2","date":1944,"nom":"Vote des femmes"},{"id":"z3","date":1945,"nom":"Premier vote femmes"},{"id":"z4","date":1974,"nom":"Majorité à 18 ans"}]},{"id":"cens","type":"texte","genre":"source","titre":"Clairval, un régime censitaire","source":"Situation imaginée pour l’exercice","blocs":["Dans le village imaginaire de Clairval vivent 300 hommes adultes. Sous un régime censitaire, seuls peuvent voter ceux qui paient au moins 200 francs d’impôt : 18 d’entre eux y parviennent."]}],"questions":[{"enonce":"Touche l’événement qui ouvre le vote à l’ensemble des hommes.","aide":"Cherche la date la plus ancienne de la frise.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent le suffrage universel masculin du droit de vote des femmes ?","aide":"Soustrais 1848 à la date du droit de vote des femmes.","type":"nombre","unite":"ans"},{"enonce":"À Clairval, quelle part des 300 hommes peut voter sous ce régime censitaire (en %) ?","aide":"Divise 18 par 300, puis multiplie par 100.","type":"nombre","unite":"%"},{"enonce":"Que peut-on dire d’un tel régime censitaire ?","aide":"Regarde qui a le droit de voter selon le texte.","type":"choix","options":[{"id":"a","texte":"Il limite le pouvoir du roi en s’appuyant sur une charte écrite célèbre"},{"id":"b","texte":"Il réserve le pouvoir politique à une petite minorité définie par sa fortune"},{"id":"c","texte":"Il désigne les magistrats par tirage au sort parmi tous les habitants"},{"id":"d","texte":"Il donne une voix égale à chaque habitant quelle que soit sa richesse"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"Le **suffrage universel masculin** est instauré en 1848."},{"cle":{"type":"nombre","valeur":96,"tolerance":0},"affichage":"96 ans","explication":"1944 − 1848 = **96 ans**."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6 %","explication":"18 ÷ 300 = 0,06 : **6 %** seulement des hommes peuvent voter."},{"cle":{"type":"choix","ids":["b"]},"explication":"Un régime censitaire lie le vote à l’impôt payé : il donne le pouvoir à une **minorité riche**."}]$ex$::jsonb),
  ('99b79047-e0f8-53b6-83fd-381be01e0b49'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Trois vagues, des reflux","competence":"analyser-document","situation":"Lina et Malik préparent un exposé. Elle pense que la démocratie ne cesse de progresser, lui n’en est pas si sûr. Ils s’appuient sur les trois vagues de démocratisation décrites par un politiste.","documents":[{"id":"deb","type":"dialogue","modele":"sms","titre":"Le débat de Lina et Malik","participants":[{"nom":"Lina","emoji":"👧","cote":"gauche"},{"nom":"Malik","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lina","texte":"Regarde la frise du cours : trois vagues de démocratisation, donc la démocratie ne fait qu’avancer !"},{"qui":"Malik","texte":"Pas si vite. Après chaque vague, il y a eu un reflux : rien n’est acquis pour toujours."},{"qui":"Lina","texte":"Mais la troisième vague a touché beaucoup de pays."}]},{"id":"vag","type":"tableau","titre":"Les trois vagues de démocratisation","source":"D’après le politiste Samuel Huntington (résumé).","colonnes":["Vague","Période","Exemples"],"lignes":[["Première","XIXe et début du XXe siècle","Europe occidentale, Amérique du Nord"],["Deuxième","Après 1945","Reconstruction, décolonisation"],["Troisième","À partir de 1974","Portugal, Espagne, Grèce, Amérique latine, Europe de l’Est après 1989"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot par lequel Malik rappelle qu’une démocratie peut reculer après avoir progressé.","aide":"Cherche le mot qui désigne un mouvement de recul.","type":"zone","document":"deb","multiple":false},{"enonce":"Touche la période de la vague qui concerne le Portugal, l’Espagne et la Grèce.","aide":"Regarde la colonne des exemples, puis celle des périodes.","type":"zone","document":"vag","multiple":false},{"enonce":"Associe chaque vague à un exemple qui la caractérise.","aide":"Suis les lignes du tableau.","type":"association","gauche":[{"id":"g0","texte":"Première vague"},{"id":"g1","texte":"Deuxième vague"},{"id":"g2","texte":"Troisième vague"}],"droite":[{"id":"d0","texte":"Europe occidentale et Amérique du Nord"},{"id":"d1","texte":"Europe de l’Est après 1989"},{"id":"d2","texte":"Reconstruction et décolonisation après 1945"}]},{"enonce":"Quelle conclusion Malik peut-il tirer du cours ?","aide":"Relis la réplique de Malik.","type":"choix","options":[{"id":"a","texte":"La démocratie est un régime récent qui n’a jamais existé avant le XIXe siècle"},{"id":"b","texte":"La démocratie est un régime irréversible dès qu’un pays l’a adoptée une fois"},{"id":"c","texte":"La démocratie est un régime réversible : chaque progrès peut être suivi d’un recul"},{"id":"d","texte":"La démocratie est un régime devenu majoritaire partout depuis la guerre froide"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m27"]},"explication":"Un **reflux** : chaque vague a été suivie d’un recul de la démocratie."},{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Ces pays sortent de dictature à partir de 1974 : c’est la **troisième vague**."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"La **première** touche l’Occident au XIXe siècle, la **deuxième** suit 1945, la **troisième** commence en 1974 et s’étend après 1989."},{"cle":{"type":"choix","ids":["c"]},"explication":"La démocratie est **rare et réversible** : les reflux rappellent qu’elle se défend."}]$ex$::jsonb),
  ('1931e51c-4c88-52ef-9010-23dbb5ab8c18'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Qui est souverain ?","competence":"lire-tableau","situation":"Deux grands penseurs ne répondent pas pareil à la question « à qui appartient la souveraineté ? ». Un tableau compare leurs idées.","documents":[{"id":"sou","type":"tableau","titre":"Deux conceptions de la souveraineté","source":"Résumé du cours.","colonnes":["","Souveraineté populaire","Souveraineté nationale"],"lignes":[["Le théoricien","Rousseau","?"],["Chaque citoyen détient","Une part de la souveraineté","Aucune part : elle est indivisible"],["Le mandat de l’élu","?","Représentatif : l’élu décide librement"]],"enteteLignes":true}],"questions":[{"enonce":"Quel théoricien est associé à la souveraineté nationale ?","aide":"Regarde la première ligne du tableau : une case est à compléter.","type":"texte","placeholder":"Un nom de famille"},{"enonce":"Complète la phrase.","aide":"L’autre colonne parle de mandat représentatif.","type":"trous","segments":["Dans la souveraineté populaire, le mandat de l’élu est ",0," : il doit obéir à ses électeurs."],"banque":["illimité","symbolique","représentatif","impératif"]},{"enonce":"Touche la case qui dit qu’aucun citoyen ne détient de part de la souveraineté nationale.","aide":"Cherche le mot « indivisible ».","type":"zone","document":"sou","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"texte","acceptes":["sieyes","emmanuel joseph sieyes","l abbe sieyes","abbe sieyes"]},"affichage":"Sieyès","explication":"**Sieyès** défend la souveraineté nationale : la Nation s’exprime par ses représentants."},{"cle":{"type":"trous","trous":[["imperatif"]]},"affichage":"impératif","explication":"Le mandat est **impératif** : l’élu est lié par la volonté de ceux qui l’ont élu."},{"cle":{"type":"zone","ids":["r1c2"]},"explication":"Dans la souveraineté nationale, la souveraineté appartient à la Nation entière : elle est **indivisible**."}]$ex$::jsonb),
  ('1931e51c-4c88-52ef-9010-23dbb5ab8c18'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Quelle forme de démocratie ?","competence":"analyser-document","situation":"Trois scènes de la vie politique montrent trois façons différentes de faire participer les citoyens. Il s’agit de bien les reconnaître.","documents":[{"id":"sce","type":"tableau","titre":"Trois scènes","source":"Scènes imaginées pour l’exercice.","colonnes":["Scène"],"lignes":[["A : tous les électeurs d’une ville répondent par « oui » ou « non » à une question posée par référendum local."],["B : des habitants réunis en conseil de quartier donnent leur avis sur un projet de parc ; le maire prendra la décision."],["C : à l’Assemblée nationale, les députés élus votent une loi après en avoir débattu."]],"enteteLignes":false}],"questions":[{"enonce":"Associe chaque scène à sa forme de démocratie.","aide":"Demande-toi qui tranche vraiment dans chaque scène.","type":"association","gauche":[{"id":"g0","texte":"Scène A"},{"id":"g1","texte":"Scène B"},{"id":"g2","texte":"Scène C"}],"droite":[{"id":"d0","texte":"Démocratie représentative"},{"id":"d1","texte":"Démocratie participative"},{"id":"d2","texte":"Démocratie directe"}]},{"enonce":"Touche la scène où ceux que l’on consulte ne tranchent pas eux-mêmes.","aide":"Qui prend la décision finale ?","type":"zone","document":"sce","multiple":false},{"enonce":"Pourquoi la Constitution française mêle-t-elle représentants et référendum ?","aide":"Pense à la phrase de la Constitution citée dans le cours.","type":"choix","options":[{"id":"a","texte":"Parce que le référendum a remplacé tous les représentants dans la Constitution"},{"id":"b","texte":"Parce que la souveraineté nationale s’exerce par les représentants et par le référendum"},{"id":"c","texte":"Parce que le peuple doit voter chaque loi sans passer par des représentants"},{"id":"d","texte":"Parce que la souveraineté appartient au chef de l’État et non au peuple"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"**A** : le peuple décide lui-même. **B** : les habitants sont associés sans trancher. **C** : des élus décident au nom du peuple."},{"cle":{"type":"zone","ids":["r1c0"]},"explication":"Dans la scène **B**, les habitants donnent leur avis, mais c’est le maire qui décide."},{"cle":{"type":"choix","ids":["b"]},"explication":"La Constitution **combine** souveraineté nationale et populaire : le peuple l’exerce « par ses représentants et par la voie du référendum »."}]$ex$::jsonb),
  ('1931e51c-4c88-52ef-9010-23dbb5ab8c18'::uuid, 3, 3, 15, 50, 3,
