xte":"Trahit la démocratie"}],"items":[{"id":"i0","texte":"Une loi adoptée par la majorité peut être contestée devant un juge"},{"id":"i1","texte":"Le gouvernement décide aussi de juger ses opposants"},{"id":"i2","texte":"Une majorité supprime le droit de réunion d’une minorité"},{"id":"i3","texte":"Un ministre est soumis à la loi comme tout citoyen"},{"id":"i4","texte":"Une loi adoptée à 60 % respecte les droits fondamentaux de chacun"}]}]}$ex$::jsonb,
