   $ex${"titre":"Élu, mais par qui ?","competence":"analyser-document","situation":"Dans une ville imaginaire, un maire est élu dans les règles. Pourtant, des habitants contestent sa légitimité. Les chiffres permettent de comprendre pourquoi.","documents":[{"id":"res","type":"tableau","titre":"Résultats de l’élection","source":"Chiffres imaginés pour l’exercice.","colonnes":["Élection imaginaire","Nombre"],"lignes":[["Électeurs inscrits","40 000"],["Votants","20 000"],["Voix obtenues par l’élu","11 000"]],"enteteLignes":true},{"id":"art","type":"texte","genre":"article","titre":"Un maire contesté","source":"Article imaginé pour l’exercice","blocs":["Le nouveau maire a été proclamé élu, et aucun recours n’a été déposé. Mais plusieurs habitants estiment qu’il ne représente pas vraiment la ville : beaucoup n’ont pas voté, certains ne sont pas inscrits là où ils vivent."]}],"questions":[{"enonce":"Quel est le taux de participation (en %) ?","aide":"Divise le nombre de votants par le nombre d’inscrits.","type":"nombre","unite":"%"},{"enonce":"Quelle part des inscrits a voté pour l’élu (en %) ? Arrondis au dixième.","aide":"Divise 11 000 par 40 000.","type":"nombre","unite":"%"},{"enonce":"Comment peut-on qualifier cette élection ?","aide":"Distingue ce que dit la loi de ce que pensent les habitants.","type":"choix","options":[{"id":"a","texte":"Elle est à la fois illégale et illégitime car la participation est de seulement 50 %"},{"id":"b","texte":"Elle est pleinement légitime car la légalité suffit toujours à fonder la légitimité"},{"id":"c","texte":"Elle est illégale puisque moins de la moitié des inscrits a voté pour l’élu"},{"id":"d","texte":"Elle est légale, mais sa légitimité peut être discutée vu la faible part des inscrits"}],"multiple":false},{"enonce":"Range chaque situation : mal-inscription, non-inscription ou abstention.","aide":"Demande-toi : est-il inscrit ? Où ? A-t-il voté ?","type":"categories","categories":[{"id":"c0","texte":"Mal-inscription"},{"id":"c1","texte":"Non-inscription"},{"id":"c2","texte":"Abstention"}],"items":[{"id":"i0","texte":"Nora, 21 ans, ne figure sur aucune liste électorale"},{"id":"i1","texte":"Paul a déménagé à Nantes sans mettre à jour son inscription"},{"id":"i2","texte":"Inès est inscrite, mais reste chez elle le jour du vote"},{"id":"i3","texte":"Clara vit à Lyon mais reste inscrite sur les listes de Brest"},{"id":"i4","texte":"Sami, 19 ans, n’est inscrit sur aucune liste électorale"}]}]}$ex$::jsonb,
