   $ex${"titre":"Dix ans de cessez-le-feu","competence":"analyser-texte","situation":"Un reportage imaginé raconte un village coupé en deux dix ans après la fin des combats. Est-ce la paix ?","documents":[{"id":"reportage","type":"texte","genre":"article","titre":"Dix ans après le cessez-le-feu","source":"Reportage imaginé pour l’exercice.","blocs":["Il y a dix ans, le cessez-le-feu a mis fin aux combats entre les deux armées. Depuis, plus un coup de feu n’a été tiré le long de la ligne de démarcation.","Mais le village de Mira reste coupé en deux : la route est fermée, les familles ne se voient plus et personne n’a obtenu de réparation pour les maisons détruites.","Aucun accord n’a réglé la question de la frontière. Chaque année, les deux gouvernements renouvellent la trêve, et chaque année les négociations s’arrêtent."]}],"questions":[{"enonce":"Touche le mot qui dit que les combats se sont arrêtés.","aide":"Cherche dans le premier paragraphe.","type":"zone","document":"reportage","multiple":false},{"enonce":"Touche, dans le dernier paragraphe, ce qui n’a jamais été réglé entre les deux États.","aide":"Il s’agit de la ligne qui sépare les deux pays.","type":"zone","document":"reportage","multiple":false},{"enonce":"Comment qualifier cette situation ?","aide":"Les armes sont silencieuses, mais est-ce que tout est réglé ?","type":"choix","options":[{"id":"a","texte":"Une paix négative : les armes se taisent, le différend demeure"},{"id":"b","texte":"Une guerre totale mobilisant toute la société du pays"},{"id":"c","texte":"Une guerre hybride mêlant cyberattaques et désinformation"},{"id":"d","texte":"Une paix positive : justice et réconciliation sont installées"}],"multiple":false},{"enonce":"Complète la définition de Galtung.","aide":"Dans le reportage, personne n’a obtenu de réparation.","type":"trous","segments":["Pour passer à une paix ",0,", il faudrait aussi ",1," les victimes et reconstruire."],"banque":["indemniser","positive","négative","bombarder"]}]}$ex$: