":"Relis la note de la médiatrice.","type":"association","gauche":[{"id":"g0","texte":"Les États"},{"id":"g1","texte":"L’ONU"},{"id":"g2","texte":"Les organisations régionales"},{"id":"g3","texte":"Les ONG"}],"droite":[{"id":"d0","texte":"Agir plus vite que l’ONU"},{"id":"d1","texte":"Négocier et garantir"},{"id":"d2","texte":"Envoyer des Casques bleus"},{"id":"d3","texte":"Garder le contact entre adversaires"}]}]}$ex$::jsonb,
