   $ex${"titre":"La guerre a-t-elle disparu ?","competence":"argumenter","situation":"Lou et Sam se disputent au sujet de la guerre classique. Un tableau leur donne quatre repères pour trancher.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Discussion entre deux élèves","source":"Dialogue écrit pour l’exercice.","participants":[{"nom":"Lou","emoji":"👧","cote":"gauche"},{"nom":"Sam","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lou","texte":"La guerre classique, c’est fini : aujourd’hui on a surtout des attentats et des cyberattaques."},{"qui":"Sam","texte":"Et les chars et l’artillerie en Ukraine en 2022, alors ?"},{"qui":"Lou","texte":"Ah oui… donc il y a plusieurs sortes de guerres en même temps ?"},{"qui":"Sam","texte":"Exactement : elles s’ajoutent, l’une ne remplace pas l’autre."}]},{"id":"reperes","type":"tableau","titre":"Quatre repères","colonnes":["Date","Événement"],"lignes":[["2001","Attentats du 11 septembre"],["2007","Cyberattaques contre l’Estonie"],["2014","Annexion de la Crimée"],["2022","Invasion de l’Ukraine"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot de Sam qui prouve que la guerre de haute intensité n’a pas disparu.","aide":"Pense à ce qu’on voit sur un front continu.","type":"zone","document":"sms","multiple":false},{"enonce":"Combien d’années séparent l’annexion de la Crimée de l’invasion de l’Ukraine ?","aide":"Soustrais 2014 à 2022.","type":"nombre","unite":"ans"},{"enonce":"Range chaque trait : guerre de haute intensité ou conflit diffus ?","aide":"Un conflit diffus n’a ni front ni traité.","type":"categories","categories":[{"id":"c0","texte":"Haute intensité"},{"id":"c1","texte":"Conflit diffus"}],"items":[{"id":"i0","texte":"Désinformation"},{"id":"i1","texte":"Cyberattaque contre des infrastructures"},{"id":"i2","texte":"Pas de traité de paix"},{"id":"i3","texte":"Chars et artillerie"},{"id":"i4","texte":"Front continu"}]},{"enonce":"Quelle conclusion Sam et Lou peuvent-ils tirer ?","aide":"Lis la dernière réplique de Sam.","type":"choix","options":[{"id":"a","texte":"Les cyberattaques ont remplacé les armées régulières"},{"id":"b","texte":"La guerre classique a totalement disparu depuis 2001"},{"id":"c","texte":"Les formes de guerre se superposent, elles ne se remplacent pas"},{"id":"d","texte":"Seul le terrorisme compte encore comme forme de guerre"}],"multiple":false}]}$ex$::jsonb,
