  ('92b98666-de2b-5f10-addb-0a8b5a5b5195'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La justice sur la colline","competence":"analyser-document","situation":"Au Rwanda, des dizaines de milliers de prisonniers attendaient un procès. Une habitante imaginaire raconte les gacaca, et un tableau en donne le bilan.","documents":[{"id":"temoin","type":"texte","genre":"recit","titre":"Sur la colline","source":"Témoignage imaginé, écrit pour l’exercice.","blocs":["On s’est assis sur l’herbe, sur la place de la colline, en plein air. Les voisins écoutaient, les rescapés racontaient. Un juge du village posait les questions.","C’était long, mais nous n’avions pas besoin d’aller jusqu’à Arusha, en Tanzanie, où siège le tribunal international."]},{"id":"bilan","type":"tableau","titre":"Les gacaca, bilan","source":"D’après le cours ; chiffres arrondis.","colonnes":["Ce qu’elles apportent","Ce qu’on leur reproche"],"lignes":[["Près de deux millions de dossiers jugés entre 2002 et 2012","Des garanties procédurales insuffisantes"],["Rapidité, proximité avec les victimes","Le risque de règlements de comptes"]]}],"questions":[{"enonce":"Touche la ville étrangère où siège le tribunal international évoqué.","aide":"C’est en Tanzanie.","type":"zone","document":"temoin","multiple":false},{"enonce":"Touche ce qu’on reproche aux gacaca sur le terrain des droits de la défense.","aide":"Cherche un mot lié à la procédure.","type":"zone","document":"bilan","multiple":false},{"enonce":"Combien de dossiers les gacaca ont-elles jugés, en moyenne, par an entre 2002 et 2012 (près de deux millions en dix ans) ?","aide":"Divise 2 000 000 par 10.","type":"nombre","unite":"dossiers"},{"enonce":"Range chaque trait : justice internationale ou justice locale ?","aide":"L’une traite l’exemplarité, l’autre la vie du village.","type":"categories","categories":[{"id":"c0","texte":"Internationale"},{"id":"c1","texte":"Locale (gacaca)"}],"items":[{"id":"i0","texte":"Se tient en plein air, près des victimes"},{"id":"i1","texte":"Juge en priorité les principaux responsables"},{"id":"i2","texte":"Traite la masse des dossiers"},{"id":"i3","texte":"Fixe la qualification de génocide"},{"id":"i4","texte":"Siège loin du pays où les crimes ont eu lieu"}]},{"enonce":"Pourquoi le Rwanda a-t-il rouvert des juridictions traditionnelles ?","aide":"Pense au nombre de prisonniers dans les prisons rwandaises.","type":"choix","options":[{"id":"a","texte":"Les tribunaux ordinaires avaient été entièrement reconstruits"},{"id":"b","texte":"Le TPIR avait déjà jugé tous les suspects"},{"id":"c","texte":"L’ONU interdisait de juger les génocidaires sur place"},{"id":"d","texte":"Plus de cent mille détenus attendaient d’être jugés"}],"multiple":false}]}$ex$::jsonb,
