  ('b7121606-c829-5476-b15b-db62fd25c312'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Déportés : mais lesquels ?","competence":"analyser-texte","situation":"Un déporté imaginaire raconte son retour en 1945. Nour y cherche les signes du silence, puis compare deux génocides.","documents":[{"id":"chiffres","type":"tableau","titre":"Deux génocides","source":"D’après le cours.","colonnes":["Victimes","Estimation","Nom du génocide"],"lignes":[["Les Juifs","Environ six millions","Shoah"],["Les Tsiganes","Entre 200 000 et 500 000","Porajmos"]],"enteteLignes":true},{"id":"temoin","type":"texte","genre":"recit","titre":"Le retour","source":"Témoignage imaginé, écrit pour l’exercice.","blocs":["Je suis rentré en 1945. À la gare, on m’a serré la main, puis on m’a demandé de ne plus en parler.","Dans les papiers officiels, j’étais classé parmi les déportés. Personne ne disait que nous avions été arrêtés parce que nous étions juifs."]}],"questions":[{"enonce":"Touche la case qui donne le nom du génocide des Tsiganes.","aide":"Le mot commence par P.","type":"zone","document":"chiffres","multiple":false},{"enonce":"Touche le mot officiel qui efface la spécificité du génocide des Juifs.","aide":"C’est le terme des papiers officiels.","type":"zone","document":"temoin","multiple":false},{"enonce":"Pourquoi le retour des déportés se heurte-t-il à l’indifférence ?","aide":"Que veut faire la société française à la Libération ?","type":"choix","options":[{"id":"a","texte":"L’État interdit toute évocation publique de la guerre"},{"id":"b","texte":"Les survivants refusent de parler à qui que ce soit"},{"id":"c","texte":"La société veut reconstruire plutôt que se souvenir"},{"id":"d","texte":"Les archives sont fermées à tous les historiens"}],"multiple":false},{"enonce":"Range chaque fait : temps du silence ou réveil de la mémoire ?","aide":"Le silence précède les années 1960 ; le réveil vient ensuite.","type":"categories","categories":[{"id":"c0","texte":"Silence (1945-années 1960)"},{"id":"c1","texte":"Réveil de la mémoire"}],"items":[{"id":"i0","texte":"Le film Shoah de Claude Lanzmann"},{"id":"i1","texte":"Le livre de Paxton sur Vichy"},{"id":"i2","texte":"Le récit d’une France massivement résistante"},{"id":"i3","texte":"Les victimes juives noyées parmi les « déportés »"},{"id":"i4","texte":"Le procès Eichmann à Jérusalem"}]}]}$ex$::jsonb,
