   $ex${"titre":"Lisbonne : l’objectif et le réel","competence":"lire-graphique","situation":"En 2000, l’Union européenne se donne un but ambitieux : devenir l’économie de la connaissance la plus compétitive du monde. Maël regarde où en sont quelques pays.","documents":[{"id":"rd","type":"graphique","forme":"barres-h","titre":"Dépense de recherche et développement","source":"Chiffres arrondis, vers 2021. La cible européenne est de 3 % du PIB.","categories":["Corée du Sud","États-Unis","Allemagne","Chine","France","Union européenne"],"series":[{"nom":"R&D","valeurs":[4.9,3.5,3.1,2.4,2.2,2.2],"teinte":"violet"}],"axeY":{"titre":"Part du PIB","unite":"%","min":0,"max":5,"pas":1},"valeurs":true},{"id":"lisb","type":"texte","genre":"source","titre":"La stratégie de Lisbonne","source":"Résumé rédigé pour l’exercice.","blocs":["En 2000, les dirigeants européens veulent faire de l’Union « l’économie de la connaissance la plus compétitive du monde ». Deux ans plus tard, à Barcelone, ils fixent une cible : consacrer 3 % du PIB à la recherche.","Vingt ans après, l’Union dans son ensemble n’a pas atteint cette cible."]}],"questions":[{"enonce":"Touche les trois pays qui dépassent la cible des 3 % du PIB.","aide":"Compare chaque barre à 3.","type":"zone","document":"rd","multiple":true},{"enonce":"De combien de points de PIB la France est-elle en dessous de la cible de 3 % ?","aide":"Soustrais la valeur de la France à 3.","type":"nombre","unite":"point"},{"enonce":"Que montre le graphique sur la stratégie de Lisbonne ?","aide":"Regarde la barre « Union européenne ».","type":"choix","options":[{"id":"a","texte":"L’Union, en moyenne, reste sous la cible qu’elle s’était fixée"},{"id":"b","texte":"Tous les pays de l’Union ont atteint la cible de 3 % du PIB"},{"id":"c","texte":"L’Union dépasse aujourd’hui la Corée du Sud et les États-Unis"},{"id":"d","texte":"La Chine consacre une part du PIB plus forte que l’Allemagne"}],"multiple":false},{"enonce":"Complète le constat du document."