   $ex${"titre":"Le départ d’Amina","competence":"analyser-document","situation":"Amina, physicienne, doit choisir entre son pays et un laboratoire étranger. Théo compare ce que disent le récit et les chiffres de trois pays imaginaires.","documents":[{"id":"amina","type":"texte","genre":"article","titre":"Une chercheuse face au choix","source":"Article imaginé pour l’exercice.","blocs":["Amina a soutenu sa thèse dans l’université de sa ville, avec un seul ordinateur pour dix doctorants et une connexion qui tombe chaque après-midi.","Un laboratoire européen lui propose un salaire cinq fois plus élevé et des équipements de pointe. Elle accepte. Son département perd sa seule spécialiste du domaine."]},{"id":"pays","type":"tableau","titre":"Trois pays imaginaires","source":"Chiffres imaginés pour l’exercice.","colonnes":["Pays","R&D (% du PIB)","Foyers connectés (%)"],"lignes":[["Pays A","3,2","95"],["Pays B","1,1","60"],["Pays C","0,4","25"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui désigne ce qui manque à Amina pour chercher dans son pays.","aide":"Cherche ce que le laboratoire européen met à sa disposition.","type":"zone","document":"amina","multiple":false},{"enonce":"Touche le pourcentage de foyers connectés du pays où la fracture numérique est la plus forte.","aide":"La fracture numérique est l’accès le plus inégal : cherche le plus petit nombre.","type":"zone","document":"pays","multiple":false},{"enonce":"Combien de fois la dépense de R&D du pays A est-elle plus élevée que celle du pays C, en part du PIB ?","aide":"Divise 3,2 par 0,4.","type":"nombre","unite":"fois"},{"enonce":"Quel phénomène illustre le départ d’Amina pour le laboratoire européen ?","aide":"Une chercheuse qualifiée quitte son pays pour un autre.","type":"choix","options":[{"id":"a","texte":"La massification de l’enseignement supérieur"},{"id":"b","texte":"La fracture numérique entre pays voisins"},{"id":"c","texte":"La fuite des cerveaux vers des pays mieux dotés"},{"id":