e ?","aide":"Pense à tout ce qui fonctionne grâce aux puces.","type":"choix","options":[{"id":"a","texte":"Ils sont produits dans un seul pays qui les offre à tous"},{"id":"b","texte":"Ils sont protégés par une convention de l’ONU sur le commerce"},{"id":"c","texte":"Ils ne servent qu’à fabriquer des appareils de loisirs grand public"},{"id":"d","texte":"Ils conditionnent l’économie, l’IA et les capacités militaires"}],"multiple":false}]}$ex$::jsonb,
